            { kind: "fill", promptUk: "Допишіть ввічливий живий регіон", promptEn: "Fill in a polite live region", language: "html", code: "<div aria-live=\"___\" role=\"status\"></div>", accepted: ["polite"], caseSensitive: true, explanationUk: "polite.", explanationEn: "polite." },
            { kind: "read", promptUk: "Чому порожній live-регіон треба створити заздалегідь, а не разом із першим текстом?", promptEn: "Why should an empty live region be created ahead of time, not together with the first text?", language: "html", code: "<!-- mount div and set text in the same frame -->", options: ["багато зчитувачів пропускають першу зміну, якщо вузол щойно з'явився", "DOM забороняє порожні div", "polite не працює на порожньому за специфікацією завжди", "треба assertive на перше повідомлення"], correctIndex: 0, explanationUk: "Спочатку вузол, потім текст.", explanationEn: "The node first, then the text." }
