          code: "<div role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"d-h\">\n  <h2 id=\"d-h\">Delete this order?</h2>\n  <button type=\"button\">Cancel</button>\n  <button type=\"button\">Delete</button>\n</div>",
